-- Phase 0: foundational schema. All student-related data is private by default.
create extension if not exists pgcrypto;
create type public.app_role as enum ('PARENT','STUDENT','ADMIN');
create table public.users (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now());
create table public.parent_profiles (user_id uuid primary key references public.users(id) on delete cascade, display_name text not null);
create table public.student_profiles (id uuid primary key default gen_random_uuid(), user_id uuid unique references public.users(id), display_name text not null, created_at timestamptz not null default now());
create table public.parent_student_relationships (parent_id uuid references public.parent_profiles(user_id) on delete cascade, student_id uuid references public.student_profiles(id) on delete cascade, primary key(parent_id,student_id));
create table public.consents (id uuid primary key default gen_random_uuid(), parent_id uuid not null references public.parent_profiles(user_id), student_id uuid not null references public.student_profiles(id), consent_type text not null, granted boolean not null, recorded_at timestamptz not null default now());
create table public.curricula (id uuid primary key default gen_random_uuid(), title text not null);
create table public.courses (id uuid primary key default gen_random_uuid(), curriculum_id uuid not null references public.curricula(id), title text not null);
create table public.units (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id), title text not null, position integer not null);
create table public.topics (id uuid primary key default gen_random_uuid(), unit_id uuid not null references public.units(id), title text not null, position integer not null);
create table public.skills (id uuid primary key default gen_random_uuid(), topic_id uuid not null references public.topics(id), code text unique not null, title text not null, mastery_threshold numeric(4,3) not null default 0.800);
create table public.skill_prerequisites (skill_id uuid references public.skills(id), prerequisite_id uuid references public.skills(id), primary key(skill_id,prerequisite_id), check(skill_id <> prerequisite_id));
create table public.course_skill_map (course_id uuid references public.courses(id), skill_id uuid references public.skills(id), primary key(course_id,skill_id));
create table public.student_courses (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), course_id uuid not null references public.courses(id), enrolled_at timestamptz not null default now(), unique(student_id,course_id));
create table public.student_skills (student_id uuid references public.student_profiles(id), skill_id uuid references public.skills(id), mastery_score numeric(4,3) not null default 0 check(mastery_score between 0 and 1), updated_at timestamptz not null default now(), primary key(student_id,skill_id));
create table public.student_misconceptions (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), skill_id uuid references public.skills(id), description text not null, resolved_at timestamptz);
create table public.learning_evidence (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), skill_id uuid not null references public.skills(id), evidence_type text not null, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table public.course_plans (id uuid primary key default gen_random_uuid(), student_course_id uuid not null references public.student_courses(id), version integer not null default 1);
create table public.course_plan_items (id uuid primary key default gen_random_uuid(), course_plan_id uuid not null references public.course_plans(id), skill_id uuid not null references public.skills(id), position integer not null, projected_date date);
create table public.lesson_schedules (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), starts_at timestamptz not null, status text not null default 'scheduled');
create table public.schedule_changes (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), previous_state jsonb not null, new_state jsonb not null, reason text not null, created_at timestamptz not null default now());
create table public.availability_preferences (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), preferences jsonb not null default '{}');
create table public.lessons (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), schedule_id uuid references public.lesson_schedules(id), status text not null default 'planned', started_at timestamptz, ended_at timestamptz);
create table public.lesson_plans (lesson_id uuid primary key references public.lessons(id), plan jsonb not null);
create table public.lesson_events (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.lessons(id), event_type text not null, payload jsonb not null default '{}', created_at timestamptz not null default now());
create table public.lesson_messages (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.lessons(id), sender text not null, content text not null, created_at timestamptz not null default now());
create table public.lesson_outcomes (lesson_id uuid primary key references public.lessons(id), outcomes jsonb not null);
create table public.questions (id uuid primary key default gen_random_uuid(), skill_id uuid not null references public.skills(id), prompt text not null, answer jsonb not null);
create table public.student_attempts (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), question_id uuid not null references public.questions(id), response jsonb not null, created_at timestamptz not null default now());
create table public.assessment_results (attempt_id uuid primary key references public.student_attempts(id), result jsonb not null);
create table public.homework_assignments (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), lesson_id uuid references public.lessons(id), due_at timestamptz);
create table public.homework_items (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.homework_assignments(id), question_id uuid not null references public.questions(id));
create table public.homework_submissions (id uuid primary key default gen_random_uuid(), assignment_id uuid not null references public.homework_assignments(id), submitted_at timestamptz not null default now());
create table public.homework_results (submission_id uuid primary key references public.homework_submissions(id), result jsonb not null);
create table public.student_memory_items (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), category text not null, content jsonb not null);
create table public.session_summaries (lesson_id uuid primary key references public.lessons(id), summary jsonb not null);
create table public.student_uploads (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), storage_path text not null, created_at timestamptz not null default now());
create table public.parent_reports (id uuid primary key default gen_random_uuid(), student_id uuid not null references public.student_profiles(id), report jsonb not null, created_at timestamptz not null default now());
create table public.ai_runs (id uuid primary key default gen_random_uuid(), lesson_id uuid references public.lessons(id), operation text not null, model text not null, prompt_version text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.tool_calls (id uuid primary key default gen_random_uuid(), ai_run_id uuid not null references public.ai_runs(id), tool_name text not null, metadata jsonb not null default '{}');
create table public.safety_events (id uuid primary key default gen_random_uuid(), student_id uuid references public.student_profiles(id), event_type text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid, action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
-- Never expose student data merely because a user has an authenticated session.
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t.tablename); end loop; end $$;
-- Course catalog is readable; write access remains server-only.
create policy "read curricula" on public.curricula for select to authenticated using (true);
create policy "read courses" on public.courses for select to authenticated using (true);
create policy "read units" on public.units for select to authenticated using (true);
create policy "read topics" on public.topics for select to authenticated using (true);
create policy "read skills" on public.skills for select to authenticated using (true);
create policy "read prerequisites" on public.skill_prerequisites for select to authenticated using (true);
create policy "read course skill map" on public.course_skill_map for select to authenticated using (true);
create function public.is_parent_of(p_student uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.parent_student_relationships r where r.parent_id=auth.uid() and r.student_id=p_student) $$;
create policy "parent or student profile read" on public.student_profiles for select to authenticated using (user_id=auth.uid() or public.is_parent_of(id));
create policy "parent own profile" on public.parent_profiles for select to authenticated using (user_id=auth.uid());
create policy "user self" on public.users for select to authenticated using (id=auth.uid());
create policy "parent relationships" on public.parent_student_relationships for select to authenticated using (parent_id=auth.uid());
create policy "parent consent read" on public.consents for select to authenticated using (parent_id=auth.uid());
-- Domain tables are denied to client roles until individually audited policies are added in later phases.
